CREATE TYPE public.app_role AS ENUM ('admin','advertiser');
CREATE TABLE public.advertisers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.advertisers TO authenticated; GRANT ALL ON public.advertisers TO service_role;
ALTER TABLE public.advertisers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text, advertiser_id uuid REFERENCES public.advertisers(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE OR REPLACE FUNCTION public.my_advertiser_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT advertiser_id FROM public.profiles WHERE user_id=auth.uid() $$;
GRANT EXECUTE ON FUNCTION public.my_advertiser_id() TO authenticated;
CREATE POLICY advertisers_read ON public.advertisers FOR SELECT TO authenticated USING (id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid() AND advertiser_id=public.my_advertiser_id());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.campaigns (id text PRIMARY KEY, advertiser_id uuid NOT NULL REFERENCES public.advertisers(id), name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','ended')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.campaigns TO authenticated; GRANT ALL ON public.campaigns TO service_role;
ALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaigns_read ON public.campaigns FOR SELECT TO authenticated USING (advertiser_id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY campaigns_insert ON public.campaigns FOR INSERT TO authenticated WITH CHECK (advertiser_id=public.my_advertiser_id());
CREATE POLICY campaigns_update ON public.campaigns FOR UPDATE TO authenticated USING (advertiser_id=public.my_advertiser_id()) WITH CHECK (advertiser_id=public.my_advertiser_id());
CREATE INDEX campaigns_advertiser_idx ON public.campaigns(advertiser_id);
CREATE TABLE public.ads (id text PRIMARY KEY, campaign_id text NOT NULL REFERENCES public.campaigns(id), advertiser_id uuid NOT NULL REFERENCES public.advertisers(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.ads TO authenticated; GRANT ALL ON public.ads TO service_role;
ALTER TABLE public.ads ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_read ON public.ads FOR SELECT TO authenticated USING (advertiser_id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_insert ON public.ads FOR INSERT TO authenticated WITH CHECK (advertiser_id=public.my_advertiser_id() AND EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND c.advertiser_id=ads.advertiser_id));
CREATE INDEX ads_campaign_idx ON public.ads(campaign_id); CREATE INDEX ads_advertiser_idx ON public.ads(advertiser_id);
CREATE TABLE public.click_events (event_id text PRIMARY KEY, ad_id text NOT NULL REFERENCES public.ads(id), campaign_id text NOT NULL REFERENCES public.campaigns(id), advertiser_id uuid NOT NULL REFERENCES public.advertisers(id), viewer_id text NOT NULL, event_time timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), ip_hash text, country char(2) NOT NULL, device text NOT NULL CHECK(device IN ('mobile','desktop','tablet','other')));
GRANT SELECT ON public.click_events TO authenticated; GRANT ALL ON public.click_events TO service_role;
ALTER TABLE public.click_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.click_events FOR SELECT TO authenticated USING (advertiser_id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX events_adv_time_idx ON public.click_events(advertiser_id,event_time DESC); CREATE INDEX events_ad_time_idx ON public.click_events(ad_id,event_time DESC);
CREATE TABLE public.aggregated_clicks (window_start timestamptz NOT NULL, advertiser_id uuid NOT NULL REFERENCES public.advertisers(id), campaign_id text NOT NULL REFERENCES public.campaigns(id), ad_id text NOT NULL REFERENCES public.ads(id), country char(2) NOT NULL, device text NOT NULL, click_count bigint NOT NULL DEFAULT 0, unique_viewers bigint NOT NULL DEFAULT 0, PRIMARY KEY(window_start,ad_id,country,device));
GRANT SELECT ON public.aggregated_clicks TO authenticated; GRANT ALL ON public.aggregated_clicks TO service_role;
ALTER TABLE public.aggregated_clicks ENABLE ROW LEVEL SECURITY;
CREATE POLICY aggregates_read ON public.aggregated_clicks FOR SELECT TO authenticated USING (advertiser_id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX agg_adv_time_idx ON public.aggregated_clicks(advertiser_id,window_start DESC); CREATE INDEX agg_camp_time_idx ON public.aggregated_clicks(campaign_id,window_start DESC);
CREATE TABLE public.suspicious_clicks (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, advertiser_id uuid NOT NULL REFERENCES public.advertisers(id), campaign_id text NOT NULL, ad_id text NOT NULL, rule text NOT NULL, subject text NOT NULL, click_count int NOT NULL, window_start timestamptz NOT NULL, detected_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(rule,subject,ad_id,window_start));
GRANT SELECT ON public.suspicious_clicks TO authenticated; GRANT ALL ON public.suspicious_clicks TO service_role;
ALTER TABLE public.suspicious_clicks ENABLE ROW LEVEL SECURITY;
CREATE POLICY suspicious_read ON public.suspicious_clicks FOR SELECT TO authenticated USING (advertiser_id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX suspicious_adv_time_idx ON public.suspicious_clicks(advertiser_id,detected_at DESC);
CREATE TABLE public.ingest_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), advertiser_id uuid NOT NULL REFERENCES public.advertisers(id), label text NOT NULL, key_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
GRANT SELECT ON public.ingest_keys TO authenticated; GRANT ALL ON public.ingest_keys TO service_role;
ALTER TABLE public.ingest_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY keys_read ON public.ingest_keys FOR SELECT TO authenticated USING (advertiser_id=public.my_advertiser_id() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.create_my_advertiser(_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(_name))<2 OR length(_name)>100 THEN RAISE EXCEPTION 'Organization name must be 2–100 characters'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE user_id=auth.uid() AND advertiser_id IS NOT NULL) THEN RAISE EXCEPTION 'Already belongs to an advertiser'; END IF; INSERT INTO public.advertisers(name) VALUES(trim(_name)) RETURNING id INTO _id; INSERT INTO public.profiles(user_id,advertiser_id) VALUES(auth.uid(),_id) ON CONFLICT(user_id) DO UPDATE SET advertiser_id=_id; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'advertiser') ON CONFLICT DO NOTHING; RETURN _id; END $$;
GRANT EXECUTE ON FUNCTION public.create_my_advertiser(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.ingest_click(_event_id text,_ad_id text,_viewer_id text,_event_time timestamptz,_country text,_device text,_ip_hash text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _ad public.ads%ROWTYPE; _window timestamptz; _inserted int; _repeat int; _ip_count int; BEGIN IF auth.uid() IS NULL AND current_setting('app.ingest_authorized',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(_event_id)<8 OR length(_event_id)>120 OR length(_viewer_id)<1 OR length(_viewer_id)>120 OR _country !~ '^[A-Z]{2}$' OR _device NOT IN ('mobile','desktop','tablet','other') OR _event_time < now()-interval '24 hours' OR _event_time > now()+interval '5 minutes' THEN RAISE EXCEPTION 'Invalid click'; END IF; SELECT * INTO _ad FROM public.ads WHERE id=_ad_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown ad'; END IF; IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') AND _ad.advertiser_id IS DISTINCT FROM public.my_advertiser_id() AND current_setting('app.ingest_authorized',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Unknown ad'; END IF; _window:=date_trunc('minute',_event_time); INSERT INTO public.click_events(event_id,ad_id,campaign_id,advertiser_id,viewer_id,event_time,ip_hash,country,device) VALUES(_event_id,_ad_id,_ad.campaign_id,_ad.advertiser_id,_viewer_id,_event_time,_ip_hash,_country,_device) ON CONFLICT DO NOTHING; GET DIAGNOSTICS _inserted=ROW_COUNT; IF _inserted=0 THEN RETURN false; END IF; INSERT INTO public.aggregated_clicks(window_start,advertiser_id,campaign_id,ad_id,country,device,click_count,unique_viewers) VALUES(_window,_ad.advertiser_id,_ad.campaign_id,_ad_id,_country,_device,1,1) ON CONFLICT(window_start,ad_id,country,device) DO UPDATE SET click_count=public.aggregated_clicks.click_count+1, unique_viewers=public.aggregated_clicks.unique_viewers+CASE WHEN NOT EXISTS(SELECT 1 FROM public.click_events e WHERE e.ad_id=_ad_id AND e.viewer_id=_viewer_id AND date_trunc('minute',e.event_time)=_window AND e.event_id<>_event_id) THEN 1 ELSE 0 END; SELECT count(*) INTO _repeat FROM public.click_events WHERE viewer_id=_viewer_id AND ad_id=_ad_id AND event_time>=_window AND event_time<_window+interval '1 minute'; IF _repeat>=50 THEN INSERT INTO public.suspicious_clicks(advertiser_id,campaign_id,ad_id,rule,subject,click_count,window_start) VALUES(_ad.advertiser_id,_ad.campaign_id,_ad_id,'viewer_repeat',_viewer_id,_repeat,_window) ON CONFLICT(rule,subject,ad_id,window_start) DO UPDATE SET click_count=EXCLUDED.click_count; END IF; IF _ip_hash IS NOT NULL THEN SELECT count(*) INTO _ip_count FROM public.click_events WHERE ip_hash=_ip_hash AND event_time>=date_trunc('minute',_event_time)+floor(extract(second from _event_time)/10)*interval '10 seconds' AND event_time<date_trunc('minute',_event_time)+(floor(extract(second from _event_time)/10)+1)*interval '10 seconds'; IF _ip_count>=100 THEN INSERT INTO public.suspicious_clicks(advertiser_id,campaign_id,ad_id,rule,subject,click_count,window_start) VALUES(_ad.advertiser_id,_ad.campaign_id,_ad_id,'ip_burst',_ip_hash,_ip_count,date_trunc('minute',_event_time)+floor(extract(second from _event_time)/10)*interval '10 seconds') ON CONFLICT(rule,subject,ad_id,window_start) DO UPDATE SET click_count=EXCLUDED.click_count; END IF; END IF; RETURN true; END $$;
GRANT EXECUTE ON FUNCTION public.ingest_click(text,text,text,timestamptz,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.touch_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profiles_touch BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_profile();